import type { CardRecord, ProgressRecord } from "./types";

export const DEFAULT_SIBLING_GAP = 12;

/**
 * Keep cards created from the same Anki note apart without globally shuffling
 * the deck. The bounded look-ahead keeps this linear for very large decks.
 */
export function separateSiblingCards(cards: CardRecord[], minimumGap = DEFAULT_SIBLING_GAP): CardRecord[] {
  if (cards.length < 2 || minimumGap < 1) return [...cards];
  const remaining = [...cards];
  const output: CardRecord[] = [];
  const lookAhead = Math.max(minimumGap * 3, 24);

  while (remaining.length) {
    const recentNotes = new Set(output.slice(-minimumGap).map((card) => card.noteId));
    const searchLimit = Math.min(remaining.length, lookAhead);
    let selectedIndex = 0;
    for (let index = 0; index < searchLimit; index += 1) {
      if (!recentNotes.has(remaining[index].noteId)) {
        selectedIndex = index;
        break;
      }
    }
    output.push(remaining.splice(selectedIndex, 1)[0]);
  }

  return output;
}

export function coverageFirstCards(cards: CardRecord[], progress: ReadonlyMap<string, ProgressRecord>): CardRecord[] {
  const unseen: CardRecord[] = [];
  const weak: CardRecord[] = [];
  const otherDue: CardRecord[] = [];
  for (const card of cards) {
    const state = progress.get(card.id);
    if (!state) unseen.push(card);
    else if (state.lastGrade === "again" || state.lastGrade === "hard") weak.push(card);
    else otherDue.push(card);
  }
  return [...unseen, ...weak, ...otherDue];
}

export function reviewFirstCards(cards: CardRecord[], progress: ReadonlyMap<string, ProgressRecord>): CardRecord[] {
  const weak: CardRecord[] = [];
  const otherDue: CardRecord[] = [];
  const unseen: CardRecord[] = [];
  for (const card of cards) {
    const state = progress.get(card.id);
    if (!state) unseen.push(card);
    else if (state.lastGrade === "again" || state.lastGrade === "hard") weak.push(card);
    else otherDue.push(card);
  }
  return [...weak, ...otherDue, ...unseen];
}

export interface DailyNewLimitResult {
  cards: CardRecord[];
  deferredCardIds: string[];
}

export interface DailyReviewLimitResult {
  cards: CardRecord[];
  deferredCardIds: string[];
}

export function limitDailyNewCards(
  cards: CardRecord[],
  progress: ReadonlyMap<string, ProgressRecord>,
  introducedToday: ReadonlySet<string>,
  dailyNewLimit: number,
  sourceDeckLimits: ReadonlyMap<string, number> = new Map(),
  introducedBySourceDeck: ReadonlyMap<string, number> = new Map(),
): DailyNewLimitResult {
  if (dailyNewLimit <= 0 && ![...sourceDeckLimits.values()].some((limit) => limit > 0)) {
    return { cards: [...cards], deferredCardIds: [] };
  }
  let availableSlots = Math.max(0, dailyNewLimit - introducedToday.size);
  const sourceSlots = new Map([...sourceDeckLimits].map(([sourceDeckId, limit]) => [
    sourceDeckId,
    limit > 0 ? Math.max(0, limit - (introducedBySourceDeck.get(sourceDeckId) ?? 0)) : Number.POSITIVE_INFINITY,
  ]));
  const included: CardRecord[] = [];
  const deferredCardIds: string[] = [];
  for (const card of cards) {
    if (progress.has(card.id) || introducedToday.has(card.id)) {
      included.push(card);
      continue;
    }
    const sourceAvailable = sourceSlots.get(card.sourceDeckId) ?? Number.POSITIVE_INFINITY;
    if ((dailyNewLimit <= 0 || availableSlots > 0) && sourceAvailable > 0) {
      if (dailyNewLimit > 0) availableSlots -= 1;
      if (sourceSlots.has(card.sourceDeckId)) sourceSlots.set(card.sourceDeckId, sourceAvailable - 1);
      included.push(card);
    } else {
      deferredCardIds.push(card.id);
    }
  }
  return { cards: included, deferredCardIds };
}

/**
 * Apply Anki-style review/day limits. New and same-day learning cards are not
 * reviews, and a review card already shown today remains available for its
 * later retry without consuming another slot.
 */
export function limitDailyReviewCards(
  cards: CardRecord[],
  reviewCardIds: ReadonlySet<string>,
  reviewedToday: ReadonlySet<string>,
  dailyReviewLimit: number,
  sourceDeckLimits: ReadonlyMap<string, number> = new Map(),
  reviewedBySourceDeck: ReadonlyMap<string, number> = new Map(),
): DailyReviewLimitResult {
  if (dailyReviewLimit <= 0 && ![...sourceDeckLimits.values()].some((limit) => limit > 0)) {
    return { cards: [...cards], deferredCardIds: [] };
  }
  let availableSlots = dailyReviewLimit > 0
    ? Math.max(0, dailyReviewLimit - reviewedToday.size)
    : Number.POSITIVE_INFINITY;
  const sourceSlots = new Map([...sourceDeckLimits].map(([sourceDeckId, limit]) => [
    sourceDeckId,
    limit > 0 ? Math.max(0, limit - (reviewedBySourceDeck.get(sourceDeckId) ?? 0)) : Number.POSITIVE_INFINITY,
  ]));
  const included: CardRecord[] = [];
  const deferredCardIds: string[] = [];
  for (const card of cards) {
    if (!reviewCardIds.has(card.id) || reviewedToday.has(card.id)) {
      included.push(card);
      continue;
    }
    const sourceAvailable = sourceSlots.get(card.sourceDeckId) ?? Number.POSITIVE_INFINITY;
    if (availableSlots > 0 && sourceAvailable > 0) {
      if (dailyReviewLimit > 0) availableSlots -= 1;
      if (sourceSlots.has(card.sourceDeckId)) sourceSlots.set(card.sourceDeckId, sourceAvailable - 1);
      included.push(card);
    } else {
      deferredCardIds.push(card.id);
    }
  }
  return { cards: included, deferredCardIds };
}
