import type { DeckLearningPolicy, LearningPolicySettings, StudyPriorityMode } from "./types";

export const MINIMUM_INTERVENING_CARD_OPTIONS = [0, 3, 5, 10, 20] as const;

export const DEFAULT_DECK_LEARNING_POLICY: DeckLearningPolicy = {
  minimumInterveningCards: 5,
  priorityMode: "balanced",
  dailyNewLimit: 0,
};

export const DEFAULT_LEARNING_POLICY: LearningPolicySettings = {
  ...DEFAULT_DECK_LEARNING_POLICY,
  siblingGuard: true,
  deckOverrides: {},
  subdeckDailyNewLimits: {},
};

function normalizePriorityMode(value: unknown): StudyPriorityMode {
  return value === "unseen" || value === "review" ? value : "balanced";
}

function normalizeMinimumInterveningCards(value: unknown): number {
  const number = Number(value);
  return MINIMUM_INTERVENING_CARD_OPTIONS.includes(number as typeof MINIMUM_INTERVENING_CARD_OPTIONS[number])
    ? number
    : DEFAULT_DECK_LEARNING_POLICY.minimumInterveningCards;
}

export function normalizeDailyNewLimit(value: unknown): number {
  const number = Number(value);
  if (!Number.isFinite(number)) return DEFAULT_DECK_LEARNING_POLICY.dailyNewLimit;
  return Math.min(9999, Math.max(0, Math.round(number)));
}

export function normalizeDeckLearningPolicy(
  policy: Partial<DeckLearningPolicy> | undefined,
): DeckLearningPolicy {
  return {
    minimumInterveningCards: normalizeMinimumInterveningCards(policy?.minimumInterveningCards),
    priorityMode: normalizePriorityMode(policy?.priorityMode),
    dailyNewLimit: normalizeDailyNewLimit(policy?.dailyNewLimit),
  };
}

export function normalizeLearningPolicy(
  policy: Partial<LearningPolicySettings> | undefined,
): LearningPolicySettings {
  return {
    ...normalizeDeckLearningPolicy(policy),
    siblingGuard: policy?.siblingGuard !== false,
    deckOverrides: Object.fromEntries(Object.entries(policy?.deckOverrides ?? {}).map(
      ([deckId, override]) => [deckId, normalizeDeckLearningPolicy(override)],
    )),
    subdeckDailyNewLimits: Object.fromEntries(Object.entries(policy?.subdeckDailyNewLimits ?? {}).map(
      ([scopeKey, limit]) => [scopeKey, normalizeDailyNewLimit(limit)],
    )),
  };
}

export function subdeckLearningPolicyKey(deckId: string, sourceDeckId: string): string {
  return `${encodeURIComponent(deckId)}/${encodeURIComponent(sourceDeckId)}`;
}

export function subdeckDailyNewLimit(
  policy: LearningPolicySettings,
  deckId: string,
  sourceDeckId: string,
): number | undefined {
  const key = subdeckLearningPolicyKey(deckId, sourceDeckId);
  return Object.prototype.hasOwnProperty.call(policy.subdeckDailyNewLimits, key)
    ? policy.subdeckDailyNewLimits[key]
    : undefined;
}

export function learningPolicyForDeck(
  policy: LearningPolicySettings,
  deckId?: string,
  sourceDeckId?: string,
): LearningPolicySettings {
  const deckPolicy = deckId && policy.deckOverrides[deckId]
    ? policy.deckOverrides[deckId]
    : policy;
  return {
    ...deckPolicy,
    dailyNewLimit: deckId && sourceDeckId
      ? subdeckDailyNewLimit(policy, deckId, sourceDeckId) ?? deckPolicy.dailyNewLimit
      : deckPolicy.dailyNewLimit,
    siblingGuard: policy.siblingGuard,
    deckOverrides: policy.deckOverrides,
    subdeckDailyNewLimits: policy.subdeckDailyNewLimits,
  };
}
