import DOMPurify from "dompurify";
import { getMedia } from "./db";
import type { CardRecord } from "./types";

export interface RenderedCard {
  question: string;
  answer: string;
  css: string;
  objectUrls: string[];
}

const EMPTY_FIELD_PATTERN = /^(?:\s|&nbsp;|<br\s*\/?>)*$/i;
const REMOTE_SCHEME = /^(?:https?:|ftp:|file:|javascript:|vbscript:|data:text\/html)/i;

function fieldHasContent(value: string | undefined): boolean {
  return Boolean(value && !EMPTY_FIELD_PATTERN.test(value));
}

function applyConditionals(template: string, fields: Record<string, string>): string {
  let output = template;
  for (let pass = 0; pass < 8; pass += 1) {
    const previous = output;
    output = output.replace(/{{([#^])([^{}]+)}}([\s\S]*?){{\/\2}}/g, (_match, mode: string, rawName: string, body: string) => {
      const name = rawName.trim().split(":").pop() ?? rawName.trim();
      const present = fieldHasContent(fields[name]);
      return (mode === "#" ? present : !present) ? body : "";
    });
    if (output === previous) break;
  }
  return output;
}

export function renderCloze(value: string, clozeNumber: number, answer: boolean): string {
  return value.replace(/{{c(\d+)::([\s\S]*?)(?:::([\s\S]*?))?}}/gi, (_match, rawNumber: string, text: string, hint?: string) => {
    if (Number(rawNumber) !== clozeNumber) return text;
    if (answer) return `<span class="cloze cloze-answer">${text}</span>`;
    const label = hint?.trim() || "…";
    return `<span class="cloze cloze-question">[${label}]</span>`;
  });
}

function stripHtml(value: string): string {
  const documentValue = new DOMParser().parseFromString(value, "text/html");
  return documentValue.body.textContent ?? "";
}

export function renderTemplate(
  template: string,
  fields: Record<string, string>,
  ordinal: number,
  answer: boolean,
  frontSide = "",
): string {
  const conditional = applyConditionals(template, fields);
  return conditional.replace(/{{([^{}]+)}}/g, (_match, rawToken: string) => {
    const token = rawToken.trim();
    if (token === "FrontSide") return frontSide;
    const parts = token.split(":");
    const fieldName = parts.at(-1)?.trim() ?? token;
    const value = fields[fieldName] ?? "";
    if (parts.includes("cloze")) return renderCloze(value, ordinal + 1, answer);
    if (parts.includes("text")) return stripHtml(value);
    if (parts.includes("type")) return answer ? value : `<span class="type-answer-placeholder">${value ? "答えを考えてください" : ""}</span>`;
    if (parts.includes("hint")) return value ? `<span class="hint">${value}</span>` : "";
    return value;
  });
}

function decodeMediaName(value: string): string {
  const trimmed = value.trim().replace(/^['"]|['"]$/g, "");
  try {
    return decodeURIComponent(trimmed).normalize("NFC");
  } catch {
    return trimmed.normalize("NFC");
  }
}

function isLocalMediaReference(value: string): boolean {
  const trimmed = value.trim();
  return Boolean(trimmed && !trimmed.startsWith("#") && !trimmed.startsWith("blob:") && !trimmed.startsWith("data:") && !REMOTE_SCHEME.test(trimmed) && !trimmed.startsWith("//"));
}

function soundTagsToAudio(html: string): string {
  return html.replace(/\[sound:([^\]]+)]/gi, (_match, name: string) => {
    const safeName = name.replaceAll('"', "&quot;");
    return `<audio controls preload="metadata" data-anki-media="${safeName}" aria-label="音声"></audio>`;
  });
}

function collectMediaNames(html: string, css: string): Set<string> {
  const names = new Set<string>();
  const documentValue = new DOMParser().parseFromString(soundTagsToAudio(html), "text/html");
  for (const element of documentValue.querySelectorAll<HTMLElement>("[src], [poster], [data-anki-media]")) {
    for (const attribute of ["src", "poster", "data-anki-media"]) {
      const value = element.getAttribute(attribute);
      if (value && isLocalMediaReference(value)) names.add(decodeMediaName(value));
    }
  }
  for (const match of css.matchAll(/url\(\s*(['"]?)(.*?)\1\s*\)/gi)) {
    if (isLocalMediaReference(match[2])) names.add(decodeMediaName(match[2]));
  }
  return names;
}

async function mediaUrls(deckId: string, names: Set<string>): Promise<{ urls: Map<string, string>; created: string[] }> {
  const urls = new Map<string, string>();
  const created: string[] = [];
  const pending = [...names];
  let nextIndex = 0;
  const worker = async () => {
    while (nextIndex < pending.length) {
      const name = pending[nextIndex++];
      const blob = await getMedia(deckId, name);
      if (!blob) continue;
      const url = URL.createObjectURL(blob);
      urls.set(name, url);
      created.push(url);
    }
  };
  // Some Anki cards reference dozens of images. Reading all blobs at once can
  // cause an avoidable memory spike on iPad, so keep a small bounded pipeline.
  await Promise.all(Array.from({ length: Math.min(4, pending.length) }, worker));
  return { urls, created };
}

function cleanCss(css: string, urls: Map<string, string>): string {
  return css
    .replace(/@import[\s\S]*?(?:;|$)/gi, "")
    .replace(/expression\s*\([^)]*\)/gi, "")
    .replace(/url\(\s*(['"]?)(.*?)\1\s*\)/gi, (_match, _quote: string, rawValue: string) => {
      const value = rawValue.trim();
      if (value.startsWith("data:") || value.startsWith("blob:")) return `url("${value.replaceAll('"', "%22")}")`;
      if (!isLocalMediaReference(value)) return "none";
      const replacement = urls.get(decodeMediaName(value));
      return replacement ? `url("${replacement}")` : "none";
    })
    .replace(/<\/style/gi, "<\\/style");
}

function sanitizeHtml(html: string, urls: Map<string, string>): string {
  const withAudio = soundTagsToAudio(html);
  const sanitized = DOMPurify.sanitize(withAudio, {
    USE_PROFILES: { html: true },
    ADD_TAGS: ["audio", "video", "source"],
    ADD_ATTR: ["controls", "preload", "poster", "playsinline", "data-anki-media"],
    FORBID_TAGS: ["script", "iframe", "object", "embed", "form", "input", "button", "textarea", "select", "option", "link", "meta", "base"],
    FORBID_ATTR: ["srcdoc", "nonce", "integrity", "formaction"],
    SANITIZE_NAMED_PROPS: true,
  });
  const documentValue = new DOMParser().parseFromString(sanitized, "text/html");
  for (const element of documentValue.body.querySelectorAll<HTMLElement>("*")) {
    for (const attribute of [...element.attributes]) {
      const name = attribute.name.toLowerCase();
      if (name.startsWith("on") || name === "srcset") element.removeAttribute(attribute.name);
    }
    const inlineStyle = element.getAttribute("style");
    if (inlineStyle) element.setAttribute("style", cleanCss(inlineStyle, urls));

    const mediaName = element.getAttribute("data-anki-media");
    if (mediaName) {
      const url = urls.get(decodeMediaName(mediaName));
      if (url) element.setAttribute("src", url);
      element.removeAttribute("data-anki-media");
    }
    for (const attributeName of ["src", "poster"]) {
      const rawValue = element.getAttribute(attributeName);
      if (!rawValue) continue;
      if (isLocalMediaReference(rawValue)) {
        const url = urls.get(decodeMediaName(rawValue));
        if (url) element.setAttribute(attributeName, url);
        else element.removeAttribute(attributeName);
      } else if (REMOTE_SCHEME.test(rawValue) || rawValue.startsWith("//")) {
        element.removeAttribute(attributeName);
      }
    }
    if (element instanceof HTMLAnchorElement) {
      element.removeAttribute("href");
      element.removeAttribute("target");
    }
  }
  return documentValue.body.innerHTML;
}

export async function renderCard(card: CardRecord): Promise<RenderedCard> {
  const questionRaw = renderTemplate(card.questionTemplate, card.fields, card.ordinal, false);
  const answerRaw = renderTemplate(card.answerTemplate, card.fields, card.ordinal, true, questionRaw);
  const names = collectMediaNames(`${questionRaw}${answerRaw}`, card.css);
  const { urls, created } = await mediaUrls(card.deckId, names);
  return {
    question: sanitizeHtml(questionRaw, urls),
    answer: sanitizeHtml(answerRaw, urls),
    css: cleanCss(card.css, urls),
    objectUrls: created,
  };
}

export function cardDocument(html: string, css: string, dark: boolean): string {
  const background = dark ? "#141515" : "#ffffff";
  const foreground = dark ? "#f4f2ed" : "#171816";
  return `<!doctype html>
<html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,viewport-fit=cover">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src blob: data:; media-src blob: data:; font-src blob: data:; style-src 'unsafe-inline';">
<style>
:root{color-scheme:${dark ? "dark" : "light"};background:${background};color:${foreground}}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:${background};color:${foreground}}
body{padding:clamp(20px,3.2vw,46px) clamp(24px,5vw,64px);font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","Hiragino Sans",sans-serif;font-size:clamp(22px,3.2vw,38px);line-height:1.6;text-align:center;overflow-wrap:anywhere}
.card{min-height:calc(100vh - clamp(40px,6.4vw,92px));display:block}
img,svg,video{display:block;max-width:100%;height:auto;max-height:62vh;object-fit:contain;margin:18px auto;border-radius:12px}audio{width:min(100%,560px);margin:20px auto}
.cloze{color:#e15d3f;font-weight:750}.cloze-question{display:inline-block;background:color-mix(in srgb,#e15d3f 12%,transparent);padding:.05em .35em;border-radius:.35em}
.hint{color:#777;font-size:.86em}.type-answer-placeholder{color:#8b8c86;font-size:.82em}hr#answer{border:0;border-top:1px solid ${dark ? "#393b38" : "#e0dfda"};margin:36px 0}
a{text-decoration:underline;text-decoration-style:dotted}table{max-width:100%;margin:auto;border-collapse:collapse}td,th{padding:.35em;border:1px solid #9995}
${css}
html>body.card{display:block!important}
</style></head><body class="card">${html}</body></html>`;
}
