/** Keeps a card edit and any newly attached local media in one IndexedDB commit. */
export async function putCardsAndMedia(cards: CardRecord[], media: MediaRecord[]): Promise<void> {
  if (!cards.length && !media.length) return;
  const db = await openDatabase();
  const transaction = db.transaction(["cards", "media"], "readwrite");
  const cardStore = transaction.objectStore("cards");
  const mediaStore = transaction.objectStore("media");
  for (const card of cards) cardStore.put(card);
  for (const record of media) mediaStore.put(record);
  await transactionDone(transaction);
}

