export interface CardBrowseResult {
  cards: CardRecord[];
  total: number;
}

function searchText(value: string): string {
  return value.replace(/<[^>]*>/g, "").replace(/&nbsp;/gi, " ").replace(/\s+/g, " ").trim().toLocaleLowerCase();
}

export function cardMatchesSearch(card: CardRecord, query: string): boolean {
  const needle = searchText(query);
  if (!needle) return true;
  return searchText([
    card.deckName,
    card.modelName,
    card.templateName,
    ...card.tags,
    ...Object.values(card.fields),
  ].join(" ")).includes(needle);
}

/**
 * Scans a deck through its IndexedDB cursor. Card bodies never need to be loaded
 * all at once, which keeps the browser usable with very large APKG imports.
 */
export async function browseCards(deckId: string, query = "", offset = 0, limit = 60): Promise<CardBrowseResult> {
  const db = await openDatabase();
  const transaction = db.transaction("cards", "readonly");
  const request = transaction.objectStore("cards").index("deckId").openCursor(IDBKeyRange.only(deckId));
  const cards: CardRecord[] = [];
  let total = 0;
  const safeOffset = Math.max(0, Math.trunc(offset));
  const safeLimit = Math.max(1, Math.min(100, Math.trunc(limit)));
  await new Promise<void>((resolve, reject) => {
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) {
        resolve();
        return;
      }
      const card = cursor.value as CardRecord;
      if (cardMatchesSearch(card, query)) {
        if (total >= safeOffset && cards.length < safeLimit) cards.push(card);
        total += 1;
      }
      cursor.continue();
    };
    request.onerror = () => reject(request.error ?? new Error("カード一覧を読み込めませんでした。"));
  });
  await transactionDone(transaction);
  return { cards, total };
}

export async function getSubdeckSummaries(deckId: string): Promise<SubdeckSummary[]> {
  const cards = await getCards(deckId);
  const summaries = new Map<string, SubdeckSummary>();
  for (const card of cards) {
    const existing = summaries.get(card.sourceDeckId);
    if (existing) existing.cardCount += 1;
    else summaries.set(card.sourceDeckId, {
      sourceDeckId: card.sourceDeckId,
      name: card.deckName,
      cardCount: 1,
    });
  }
  return [...summaries.values()].sort((a, b) => a.name.localeCompare(b.name, "ja", { numeric: true }));
}

