async function deleteByDeckIndex(store: IDBObjectStore, deckId: string): Promise<void> {
  const index = store.index("deckId");
  await new Promise<void>((resolve, reject) => {
    const request = index.openKeyCursor(IDBKeyRange.only(deckId));
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) {
        resolve();
        return;
      }
      store.delete(cursor.primaryKey);
      cursor.continue();
    };
    request.onerror = () => reject(request.error ?? new Error("Deck cleanup failed"));
  });
}

export async function deleteDeck(deckId: string): Promise<void> {
  const db = await openDatabase();
  const transaction = db.transaction(["decks", "cards", "media", "reviews", "progress", "reviewFlags", "sessions", "imports", "dailyNew", "dailyReview", "todayOnlyLimits"], "readwrite");
  transaction.objectStore("decks").delete(deckId);
  transaction.objectStore("sessions").delete(deckId);
  transaction.objectStore("imports").delete(deckId);
  transaction.objectStore("dailyNew").delete(deckId);
  transaction.objectStore("dailyReview").delete(deckId);
  await Promise.all([
    deleteByDeckIndex(transaction.objectStore("cards"), deckId),
    deleteByDeckIndex(transaction.objectStore("media"), deckId),
    deleteByDeckIndex(transaction.objectStore("reviews"), deckId),
    deleteByDeckIndex(transaction.objectStore("progress"), deckId),
    deleteByDeckIndex(transaction.objectStore("reviewFlags"), deckId),
    deleteByDeckIndex(transaction.objectStore("todayOnlyLimits"), deckId),
  ]);
  await transactionDone(transaction);
}

export async function deletePartialImport(deckId: string): Promise<void> {
  const db = await openDatabase();
  const transaction = db.transaction(["decks", "cards", "media", "imports"], "readwrite");
  const completedDeck = await requestValue(
    transaction.objectStore("decks").get(deckId) as IDBRequest<DeckRecord | undefined>,
  );
  if (completedDeck) {
    transaction.abort();
    throw new Error("読み込み済みデッキのデータは削除できません。");
  }
  transaction.objectStore("imports").delete(deckId);
  await Promise.all([
    deleteByDeckIndex(transaction.objectStore("cards"), deckId),
    deleteByDeckIndex(transaction.objectStore("media"), deckId),
  ]);
  await transactionDone(transaction);
}

export function shouldReplaceSavedSession(
  current: SavedSessionRecord | undefined,
  incoming: SavedSessionRecord,
): boolean {
  return !current || incoming.updatedAt >= current.updatedAt;
}

export function progressFromReviewHistory(
  deckId: string,
  cardId: string,
  reviews: readonly ReviewRecord[],
): ProgressRecord | undefined {
  const latest = reviews.at(-1);
  if (!latest) return undefined;
  return {
    key: `${deckId}:${cardId}`,
    deckId,
    cardId,
    lastGrade: latest.grade,
    reviewCount: reviews.length,
    correctCount: reviews.filter((review) => review.grade === "good" || review.grade === "easy").length,
    lapseCount: reviews.filter((review) => review.grade === "again").length,
    lastReviewedAt: latest.reviewedAt,
    firstReviewedAt: reviews[0]?.reviewedAt,
    dueAt: latest.dueAt ?? dueAtForGrade(latest.grade, latest.reviewedAt),
    schedulerState: latest.schedulerState ? { ...latest.schedulerState } : undefined,
  };
}

async function putSessionIfNewer(store: IDBObjectStore, session: SavedSessionRecord): Promise<void> {
  const current = await requestValue(store.get(session.deckId) as IDBRequest<SavedSessionRecord | undefined>);
  if (shouldReplaceSavedSession(current, session)) store.put(session);
}

export async function saveReview(review: ReviewRecord, savedSession?: SavedSessionRecord): Promise<ProgressRecord> {
  const db = await openDatabase();
  const transaction = db.transaction(["reviews", "progress", "decks", "sessions"], "readwrite");
  transaction.objectStore("reviews").add(review);
  if (savedSession) await putSessionIfNewer(transaction.objectStore("sessions"), savedSession);

  const progressStore = transaction.objectStore("progress");
  const progressKey = `${review.deckId}:${review.cardId}`;
  const previous = await requestValue(
    progressStore.get(progressKey) as IDBRequest<ProgressRecord | undefined>,
  );
  const isCorrect = review.grade === "good" || review.grade === "easy";
  const progress: ProgressRecord = {
    key: progressKey,
    deckId: review.deckId,
    cardId: review.cardId,
    lastGrade: review.grade,
    reviewCount: (previous?.reviewCount ?? 0) + 1,
    correctCount: (previous?.correctCount ?? 0) + (isCorrect ? 1 : 0),
    lapseCount: (previous?.lapseCount ?? 0) + (review.grade === "again" ? 1 : 0),
    lastReviewedAt: review.reviewedAt,
    firstReviewedAt: previous?.firstReviewedAt ?? (previous ? undefined : review.reviewedAt),
    dueAt: review.dueAt ?? dueAtForGrade(review.grade, review.reviewedAt),
    schedulerState: review.schedulerState ? { ...review.schedulerState } : previous?.schedulerState,
  };
  progressStore.put(progress);

  const deckStore = transaction.objectStore("decks");
  const deck = await requestValue(deckStore.get(review.deckId) as IDBRequest<DeckRecord | undefined>);
  if (deck) {
    deck.reviewCount += 1;
    deck.correctCount += isCorrect ? 1 : 0;
    deck.lastStudiedAt = review.reviewedAt;
    deckStore.put(deck);
  }

  await transactionDone(transaction);
  return progress;
}

