function emptyStudyScopeTodayCounts(): StudyScopeTodayCounts {
  return { unseenCount: 0, introducedCount: 0, introducedUnreviewedCount: 0, dueReviewCount: 0, reviewedCount: 0, reviewedDueCount: 0 };
}

export async function getDeckTodayCounts(
  deckId: string,
  now: number,
  dayStartedAt: number,
  hiddenCardIds: ReadonlySet<string> = new Set(),
): Promise<DeckTodayCounts> {
  const db = await openDatabase();
  const progressTransaction = db.transaction("progress", "readonly");
  const progressDone = transactionDone(progressTransaction);
  const progressRequest = progressTransaction.objectStore("progress").index("deckId").openCursor(IDBKeyRange.only(deckId));
  const progress = new Map<string, ProgressRecord>();
  const progressRead = new Promise<void>((resolve, reject) => {
    progressRequest.onsuccess = () => {
      const cursor = progressRequest.result;
      if (!cursor) {
        resolve();
        return;
      }
      const record = cursor.value as ProgressRecord;
      progress.set(record.cardId, record);
      cursor.continue();
    };
    progressRequest.onerror = () => reject(progressRequest.error ?? new Error("Today's progress could not be read"));
  });
  const [dailyNewState, dailyReviewState] = await Promise.all([
    getDailyNewState(deckId, dayStartedAt),
    getDailyReviewState(deckId, dayStartedAt),
    progressRead,
  ]);
  await progressDone;
  const introduced = new Set(dailyNewState.cardIds);
  const reviewed = new Set(dailyReviewState.cardIds);
  const parent = emptyStudyScopeTodayCounts();
  const subdecks: Record<string, StudyScopeTodayCounts> = {};
  const transaction = db.transaction("cards", "readonly");
  const request = transaction.objectStore("cards").index("deckId").openCursor(IDBKeyRange.only(deckId));
  await new Promise<void>((resolve, reject) => {
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) {
        resolve();
        return;
      }
      const card = cursor.value as CardRecord;
      const scope = subdecks[card.sourceDeckId] ??= emptyStudyScopeTodayCounts();
      const wasIntroduced = introduced.has(card.id);
      if (wasIntroduced) {
        parent.introducedCount += 1;
        scope.introducedCount += 1;
      }
      if (reviewed.has(card.id)) {
        parent.reviewedCount += 1;
        scope.reviewedCount += 1;
      }
      if (!hiddenCardIds.has(card.id)) {
        const state = progress.get(card.id);
        if (!state) {
          parent.unseenCount += 1;
          scope.unseenCount += 1;
          if (wasIntroduced) {
            parent.introducedUnreviewedCount += 1;
            scope.introducedUnreviewedCount += 1;
          }
        } else if (!state.schedulerState?.suspended && progressDueAt(state) <= now) {
          parent.dueReviewCount += 1;
          scope.dueReviewCount += 1;
          if (reviewed.has(card.id)) {
            parent.reviewedDueCount += 1;
            scope.reviewedDueCount += 1;
          }
        }
      }
      cursor.continue();
    };
    request.onerror = () => reject(request.error ?? new Error("Today's deck counts could not be read"));
  });
  await transactionDone(transaction);
  return { deckId, dayStartedAt, parent, subdecks };
}

