function latestReviewFromIndex(
  index: IDBIndex,
  deckId: string,
  eligibleCardIds?: ReadonlySet<string>,
): Promise<ReviewRecord | undefined> {
  return new Promise((resolve, reject) => {
    const request = index.openCursor(IDBKeyRange.only(deckId), "prev");
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) {
        resolve(undefined);
        return;
      }
      const review = cursor.value as ReviewRecord;
      if (!eligibleCardIds || eligibleCardIds.has(review.cardId)) {
        resolve(review);
        return;
      }
      cursor.continue();
    };
    request.onerror = () => reject(request.error ?? new Error("Review lookup failed"));
  });
}

