  const current = await requestValue(store.get(deckId) as IDBRequest<DailyNewStateRecord | undefined>);
  const state = current?.dayStartedAt === dayStartedAt
    ? current
    : { deckId, dayStartedAt, cardIds: [], updatedAt: Date.now() } satisfies DailyNewStateRecord;
