export async function getTodayOnlyLimits(dayStartedAt: number): Promise<TodayOnlyLimitRecord[]> {
  const db = await openDatabase();
  const transaction = db.transaction("todayOnlyLimits", "readonly");
  const request = transaction.objectStore("todayOnlyLimits").openCursor();
  const records: TodayOnlyLimitRecord[] = [];
  await new Promise<void>((resolve, reject) => {
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) {
        resolve();
        return;
      }
      const record = cursor.value as TodayOnlyLimitRecord;
      if (record.dayStartedAt === dayStartedAt) records.push(record);
      cursor.continue();
    };
    request.onerror = () => reject(request.error ?? new Error("Today's limits could not be read"));
  });
  await transactionDone(transaction);
  return records;
}

