export async function getSettings<T extends AppSettings>(fallback: T): Promise<T> {
  const db = await openDatabase();
  const transaction = db.transaction("settings", "readonly");
  const stored = await requestValue(transaction.objectStore("settings").get("app") as IDBRequest<T | undefined>);
  return stored ? {
    ...fallback,
    ...stored,
    bindings: { ...fallback.bindings, ...stored.bindings },
    sessionDefaults: { ...fallback.sessionDefaults, ...stored.sessionDefaults },
  } : fallback;
}

