function persistSettings(): Promise<void> {
  const snapshot = structuredClone(settings);
  const write = settingsSaveQueue.then(() => putSettings(snapshot));
  settingsSaveQueue = write.catch(() => undefined);
  return write;
}

function queueSessionWrite<T>(operation: () => Promise<T>): Promise<T> {
  const write = sessionWriteQueue.then(operation);
  sessionWriteQueue = write.then(() => undefined, () => undefined);
  return write;
}

function stampSessionSnapshot(snapshot: SavedSessionRecord): SavedSessionRecord {
  sessionSnapshotTimestamp = Math.max(Date.now(), snapshot.updatedAt, sessionSnapshotTimestamp + 1);
  return { ...snapshot, updatedAt: sessionSnapshotTimestamp };
}

function persistSavedSession(snapshot: SavedSessionRecord): Promise<void> {
  return queueSessionWrite(() => putSavedSession(snapshot));
}

function removeSavedSession(deckId: string): Promise<void> {
  return queueSessionWrite(() => deleteSavedSession(deckId));
}

function saveSettingsInBackground(): void {
  void persistSettings().catch(() => {
    showToast("設定を保存できませんでした。iPadの空き容量を確認してください。", 6000);
  });
}

async function flushStateForBackup(): Promise<void> {
  await persistSettings();
  if (session && activeDeck && !session.complete && !showingTodayHiddenPrompt) {
    await persistSavedSession(createSavedSessionSnapshot());
  }
  await Promise.all([settingsSaveQueue, sessionWriteQueue, todayOnlyLimitWriteQueue]);
}

function queueInternalBackup(reason: BackupReason): Promise<BackupSummary> {
  const operation = backupWriteQueue.then(async () => {
    await flushStateForBackup();
    const snapshot = await createBackupSnapshot(APP_VERSION, reason);
    const summary = await saveInternalBackup(snapshot);
    backupSummaries = await listBackupSummaries();
    return summary;
  });
  backupWriteQueue = operation.then(() => undefined, () => undefined);
  return operation;
}

function startAutomaticBackups(): void {
  window.clearInterval(automaticBackupTimer);
  automaticBackupTimer = window.setInterval(() => {
    if (document.visibilityState === "visible") void queueInternalBackup("automatic").catch(() => undefined);
  }, AUTOMATIC_BACKUP_INTERVAL_MS);
}

async function exportBackupFile(): Promise<void> {
  await flushStateForBackup();
  const snapshot = await createBackupSnapshot(APP_VERSION, "manual", true);
  const fileName = backupFileName(snapshot.createdAt);
  const file = new File([JSON.stringify(snapshot)], fileName, { type: "application/json" });
  const shareNavigator = navigator as Navigator & { canShare?: (data: ShareData) => boolean };
  if (navigator.share && shareNavigator.canShare?.({ files: [file] })) {
    await navigator.share({ files: [file], title: "APKG Simulator バックアップ" });
    return;
  }
  const url = URL.createObjectURL(file);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = fileName;
  anchor.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 30_000);
}

async function restoreFromBackup(snapshot: BackupSnapshot): Promise<void> {
  const availableDeckIds = new Set(decks.map((deck) => deck.id));
  const missingDecks = snapshot.deckStates.filter((state) => !availableDeckIds.has(state.id));
  if (missingDecks.length) {
    throw new Error(`バックアップ対象のデッキが${missingDecks.length}件ありません。元のAPKGを先に読み込んでください。`);
  }
  await restoreBackupSnapshot(snapshot);
  window.location.reload();
}

