function reviewTimingForDeck(deckId?: string): ReviewTiming {
  const schedule = currentReviewSchedule();
  const options = currentDeckOptions();
  return {
    intervals: deckId && schedule.deckOverrides[deckId]
      ? schedule.deckOverrides[deckId]
      : schedule.intervals,
    dayStartMinutes: schedule.dayStartMinutes,
    lookaheadMinutes: schedule.lookaheadMinutes,
    scheduler: presetForDeck(options, deckId),
    sourceDeckSchedulers: deckId ? Object.fromEntries((deckSubdecks.get(deckId) ?? []).map((subdeck) => [
      subdeck.sourceDeckId,
      presetForDeck(options, deckId, subdeck.sourceDeckId),
    ])) : undefined,
  };
}

