async function refreshLibraryTodayStats(): Promise<void> {
  const requestId = ++deckTodayCountsRequest;
  const now = Date.now();
  const dayStartedAt = studyDayStartAt(now, currentReviewSchedule().dayStartMinutes);
  const entries: [string, DeckTodayCounts][] = [];
  try {
    // Read one large deck at a time so iPadOS does not need to decode several
    // card stores concurrently. The cursor keeps memory use bounded.
    for (const deck of decks) {
      if (requestId !== deckTodayCountsRequest) return;
      const counts = await getDeckTodayCounts(
        deck.id,
        now,
        dayStartedAt,
        todayHiddenCardIds(settings.todayHidden, deck.id, now),
      );
      entries.push([deck.id, counts]);
    }
  } catch {
    if (requestId === deckTodayCountsRequest) {
      for (const element of document.querySelectorAll<HTMLElement>("[data-today-stats-deck]")) {
        element.innerHTML = `<span class="today-quota-loading">今日の枚数を取得できません</span>`;
      }
    }
    return;
  }
  if (requestId !== deckTodayCountsRequest) return;
  deckTodayCounts = new Map(entries);
  applyLibraryTodayStats();
}

