function bindLibraryEvents(): void {
  const fileInput = document.querySelector<HTMLInputElement>("#apkg-input");
  for (const button of document.querySelectorAll<HTMLButtonElement>("[data-import]")) {
    button.addEventListener("click", () => fileInput?.click());
  }
  fileInput?.addEventListener("change", () => {
    const file = fileInput.files?.[0];
    fileInput.value = "";
    if (file) void handleImport(file);
  });
  for (const card of document.querySelectorAll<HTMLElement>("[data-deck-card]")) {
    const openDeck = () => void openDeckForStudy(card.dataset.deckCard ?? "");
    card.addEventListener("click", (event) => {
      if ((event.target as Element).closest("button,details")) return;
      openDeck();
    });
    card.addEventListener("keydown", (event) => {
      if (event.target !== card) return;
      if (event.key !== "Enter" && event.key !== " ") return;
      event.preventDefault();
      openDeck();
    });
  }
  for (const button of document.querySelectorAll<HTMLButtonElement>("[data-subdeck-id]")) {
    button.addEventListener("click", () => void openDeckForStudy(button.dataset.parentDeck ?? "", button.dataset.subdeckId));
  }
  for (const button of document.querySelectorAll<HTMLButtonElement>("[data-deck-menu]")) {
    button.addEventListener("click", () => openDeckDialog(button.dataset.deckMenu ?? ""));
  }
  for (const button of document.querySelectorAll<HTMLButtonElement>("[data-sprint-deck]")) {
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      const dialog = document.querySelector<HTMLDialogElement>("#sprint-dialog");
      if (!dialog) return;
      dialog.dataset.deckId = button.dataset.sprintDeck ?? "";
      dialog.showModal();
    });
  }
  for (const button of document.querySelectorAll<HTMLButtonElement>("[data-sprint-minutes]")) {
    button.addEventListener("click", () => void startSprintFromLibrary(Number(button.dataset.sprintMinutes)));
  }
  document.querySelector<HTMLButtonElement>("#start-custom-sprint")?.addEventListener("click", () => {
    const input = document.querySelector<HTMLInputElement>("#sprint-custom-minutes");
    const minutes = normalizeSprintMinutes(input?.valueAsNumber);
    if (!minutes) {
      showToast("Sprint時間を1分以上で入力してください。");
      input?.focus();
      return;
    }
    if (input) input.value = String(minutes);
    void startSprintFromLibrary(minutes);
  });
  document.querySelector<HTMLButtonElement>("[data-settings]")?.addEventListener("click", openSettings);
  document.querySelector<HTMLButtonElement>("[data-update]")?.addEventListener("click", (event) => {
    void updateApplication(event.currentTarget as HTMLButtonElement);
  });
  document.querySelector<HTMLButtonElement>("[data-install]")?.addEventListener("click", () => document.querySelector<HTMLDialogElement>("#install-dialog")?.showModal());
  bindDialogCloseButtons();
}

async function startSprintFromLibrary(minutes: number): Promise<void> {
  const dialog = document.querySelector<HTMLDialogElement>("#sprint-dialog");
  const deck = decks.find((item) => item.id === dialog?.dataset.deckId);
  const duration = normalizeSprintMinutes(minutes);
  if (!deck || !duration) return;
  dialog?.close();
  void requestStudyFullscreen();
  await startSession(deck, { ...DEFAULT_SESSION_OPTIONS, sprintMinutes: duration });
}

function bindDialogCloseButtons(scope: ParentNode = document): void {
  for (const button of scope.querySelectorAll<HTMLButtonElement>("[data-close-dialog]")) {
    button.addEventListener("click", () => button.closest("dialog")?.close());
  }
}

async function loadSubdeckSummaries(targetDecks: DeckRecord[] = decks): Promise<void> {
  const entries = await Promise.all(targetDecks.map(async (deck) => {
    if (deck.subdecks?.length) return [deck.id, deck.subdecks] as const;
    const summaries = await getSubdeckSummaries(deck.id);
    deck.subdecks = summaries;
    await putDeck(deck);
    return [deck.id, summaries] as const;
  }));
  deckSubdecks = new Map(entries);
}

async function handleImport(file: File): Promise<void> {
  if (importingApkg) {
    showToast("別のAPKGを読み込み中です。完了してから次のファイルを選んでください。", 5000);
    return;
  }
  importingApkg = true;
  const overlay = document.createElement("div");
  overlay.className = "import-overlay";
  overlay.innerHTML = `<div class="import-panel" role="status" aria-live="polite"><div class="brand-mark">A</div><h2>${escapeHtml(file.name)}</h2><p id="import-message">読み込みを開始しています</p><p class="import-warning" id="import-warning" hidden></p><div class="import-progress"><span id="import-progress-bar"></span></div></div>`;
  document.body.append(overlay);
  try {
    const result = await importApkg(file, (progress) => {
      const message = overlay.querySelector<HTMLElement>("#import-message");
      const warning = overlay.querySelector<HTMLElement>("#import-warning");
      const bar = overlay.querySelector<HTMLElement>("#import-progress-bar");
      if (message) message.textContent = progress.message;
      if (warning && progress.warning) {
        warning.hidden = false;
        warning.textContent = progress.warning;
      }
      if (bar) bar.style.width = `${progress.total ? Math.max(4, Math.round((progress.completed / progress.total) * 100)) : 8}%`;
    });
    [decks, importJobs] = await Promise.all([getDecks(), getImportJobs()]);
    await loadSubdeckSummaries();
    renderLibrary();
    if (result.outcome === "existing") showToast(`「${result.deck.name}」は読み込み済みです。学習履歴はそのまま残っています。`, 5200);
    else showToast(`「${result.deck.name}」を${result.deck.cardCount.toLocaleString()}枚${result.outcome === "resumed" ? "、途中から再開して" : ""}読み込みました`, 5200);
  } catch (error) {
    importJobs = await getImportJobs().catch(() => importJobs);
    renderLibrary();
    const message = error instanceof Error ? error.message : "読み込みに失敗しました。";
    showToast(message, 7200);
  } finally {
    overlay.remove();
    importingApkg = false;
  }
}

async function openDeckForStudy(deckId: string, sourceDeckId?: string): Promise<void> {
  const deck = decks.find((item) => item.id === deckId);
  if (!deck) return;
  const subdeck = sourceDeckId === undefined
    ? undefined
    : deckSubdecks.get(deckId)?.find((item) => item.sourceDeckId === sourceDeckId);
  if (sourceDeckId !== undefined && !subdeck) {
    showToast("サブデッキ情報を読み直してください。");
    return;
  }
  void requestStudyFullscreen();
  await sessionWriteQueue;
  let savedSession = await getSavedSession(deckId);
  if (savedSession?.sourceDeckId !== sourceDeckId) savedSession = undefined;
  if (savedSession && savedSession.position >= savedSession.cardIds.length) {
    await removeSavedSession(deckId);
    savedSession = undefined;
  }
  if (savedSession) await resumeSavedSession(deck, savedSession, subdeck);
  else await startSession(deck, { ...DEFAULT_SESSION_OPTIONS }, subdeck);
}

function createSavedSessionSnapshot(): SavedSessionRecord {
  if (!session || !activeDeck) throw new Error("保存する演習がありません");
  const snapshot = session.snapshot(activeDeck.id, lastSessionOptions, activeSubdeck?.sourceDeckId);
  if ((lastSessionOptions.sprintMinutes ?? 0) > 0) snapshot.sprintRemainingMs = Math.max(0, Math.round(sprintRemainingMs));
  return stampSessionSnapshot(snapshot);
}

async function refreshTodayHiddenState(deckId: string): Promise<void> {
  const before = settings.todayHidden ?? [];
  const active = activeTodayHiddenRecords(before);
  settings.todayHidden = active;
  activeTodayHidden = todayHiddenCardIds(active, deckId);
  const buriedBefore = settings.siblingBuried ?? [];
  const buriedActive = activeTodayHiddenRecords(buriedBefore);
  settings.siblingBuried = buriedActive;
  activeSiblingBuried = todayHiddenCardIds(buriedActive, deckId);
  if (active.length !== before.length || buriedActive.length !== buriedBefore.length) await persistSettings().catch(() => undefined);
}

function dailyNewCardIdsForDay(
  state: DailyNewStateRecord,
  progress: readonly ProgressRecord[],
  dayStartedAt: number,
): Set<string> {
  const cardIds = new Set(state.cardIds);
  // This fallback covers a first answer that was saved immediately before an
  // interrupted daily-counter write. Normal operation records the card when
  // its question is first displayed, before an answer is required.
  for (const item of progress) {
    const firstReviewedAt = item.firstReviewedAt
      ?? (item.reviewCount === 1 ? item.lastReviewedAt : undefined);
    if (firstReviewedAt !== undefined && firstReviewedAt >= dayStartedAt) cardIds.add(item.cardId);
  }
  return cardIds;
}

function dailyLimitSessionConfiguration(
  deckId: string,
  subdeck: SubdeckSummary | undefined,
  allCards: readonly CardRecord[],
  progress: readonly ProgressRecord[],
  introducedCardIds: ReadonlySet<string>,
  reviewedCardIds: ReadonlySet<string>,
  dayStartedAt: number,
): {
  policy: LearningPolicySettings;
  introducedCardIds: ReadonlySet<string>;
  sourceDeckNewLimits: ReadonlyMap<string, number>;
  reviewCardIds: ReadonlySet<string>;
  reviewedCardIds: ReadonlySet<string>;
  dailyReviewLimit: number;
  sourceDeckReviewLimits: ReadonlyMap<string, number>;
} {
  const policySettings = currentLearningPolicy();
  const dailySettings = currentDailyLimitSettings();
  const sourceDeckId = subdeck?.sourceDeckId;
  const knownSourceDeckIds = deckSubdecks.get(deckId)?.map((item) => item.sourceDeckId)
    ?? [...new Set(allCards.map((card) => card.sourceDeckId))];
  const resolution = resolveDailyLimitSession(
    dailySettings,
    todayOnlyLimits,
    deckId,
    sourceDeckId,
    knownSourceDeckIds,
    dayStartedAt,
  );
  const selectedCardIds = sourceDeckId
    ? new Set(allCards.filter((card) => card.sourceDeckId === sourceDeckId).map((card) => card.id))
    : undefined;
  const introducedForSession = resolution.countFromParent
    ? introducedCardIds
    : new Set([...introducedCardIds].filter((cardId) => selectedCardIds?.has(cardId)));
  const reviewedForSession = resolution.countFromParent
    ? reviewedCardIds
    : new Set([...reviewedCardIds].filter((cardId) => selectedCardIds?.has(cardId)));
  const reviewIds = new Set(progress
    .filter((item) => !introducedCardIds.has(item.cardId) && (!selectedCardIds || selectedCardIds.has(item.cardId)))
    .map((item) => item.cardId));
  const sourceDeckNewLimits = new Map<string, number>();
  const sourceDeckReviewLimits = new Map<string, number>();
  for (const [candidate, limits] of resolution.sourceDeckLimits) {
    sourceDeckNewLimits.set(candidate, limits.newCards);
    sourceDeckReviewLimits.set(candidate, limits.reviews);
  }
  const policy = resolveLearningPolicyForDeck(policySettings, deckId, sourceDeckId);
  return {
    policy: { ...policy, dailyNewLimit: resolution.overall.newCards },
    introducedCardIds: introducedForSession,
    sourceDeckNewLimits,
    reviewCardIds: reviewIds,
    reviewedCardIds: reviewedForSession,
    dailyReviewLimit: resolution.overall.reviews,
    sourceDeckReviewLimits,
  };
}

async function startSession(
  deck: DeckRecord,
  options: SessionOptions,
  subdeck = activeSubdeck,
  onlyCardIds?: ReadonlySet<string>,
): Promise<void> {
  undoableOperations = [];
  options = { ...options, sprintMinutes: normalizeSprintMinutes(options.sprintMinutes ?? 0) };
  stopSprintTimer();
  sprintRemainingMs = Math.max(0, (options.sprintMinutes ?? 0) * 60_000);
  sprintExpired = false;
  showingTodayHiddenPrompt = false;
  await refreshTodayHiddenState(deck.id);
  const reviewTiming = reviewTimingForDeck(deck.id);
  const dayStartedAt = studyDayStartAt(Date.now(), reviewTiming.dayStartMinutes);
  const [allCards, progress, reviewFlags, dailyNewState, dailyReviewState] = await Promise.all([
    getCards(deck.id),
    getProgress(deck.id),
    getReviewFlags(deck.id),
    getDailyNewState(deck.id, dayStartedAt),
    getDailyReviewState(deck.id, dayStartedAt),
  ]);
  activeDailyNewCardIds = dailyNewCardIdsForDay(dailyNewState, progress, dayStartedAt);
  activeDailyNewDayStartedAt = dayStartedAt;
  activeDailyReviewCardIds = new Set(dailyReviewState.cardIds);
  activeDailyReviewDayStartedAt = dailyReviewState.dayStartedAt;
  const dailyConfiguration = dailyLimitSessionConfiguration(
    deck.id,
    subdeck,
    allCards,
    progress,
    activeDailyNewCardIds,
    activeDailyReviewCardIds,
    dayStartedAt,
  );
  const scopedCards = subdeck ? allCards.filter((card) => card.sourceDeckId === subdeck.sourceDeckId) : allCards;
  activeSessionCards = onlyCardIds ? scopedCards.filter((card) => onlyCardIds.has(card.id)) : scopedCards;
  const cards = activeSessionCards.filter((card) => !activeTodayHidden.has(card.id) && !activeSiblingBuried.has(card.id));
  activeReviewFlags = new Set(reviewFlags.map((item) => item.cardId));
  const nextSession = new StudySession(
    cards,
    progress,
    options,
    undefined,
    activeReviewFlags,
    reviewTiming,
    dailyConfiguration.policy,
    dailyConfiguration.introducedCardIds,
    dailyConfiguration.sourceDeckNewLimits,
    dailyConfiguration.reviewCardIds,
    dailyConfiguration.reviewedCardIds,
    dailyConfiguration.dailyReviewLimit,
    dailyConfiguration.sourceDeckReviewLimits,
  );
  if (!nextSession.initialCount) {
    activeDeck = deck;
    activeSubdeck = subdeck;
    session = nextSession;
    lastSessionOptions = { ...options, sprintMinutes: 0 };
    sprintRemainingMs = 0;
    paused = false;
    renderStudyScreen();
    if (!activeSessionCards.some((card) => activeTodayHidden.has(card.id))) {
      const limitReason = nextSession.deferredNewCards > 0 && nextSession.deferredReviewCards > 0
        ? "今日の新規・復習上限に達しています。"
        : nextSession.deferredNewCards > 0
          ? "今日の新規上限に達しています。"
          : nextSession.deferredReviewCards > 0
            ? "今日の復習上限に達しています。"
            : undefined;
      showToast(limitReason
        ?? (options.filter === "missed" ? "苦手カードはまだありません。" : options.filter === "flagged" ? "要復習マークのカードはありません。" : "条件に合うカードがありません。"));
    }
    return;
  }
  activeDeck = deck;
  activeSubdeck = subdeck;
  session = nextSession;
  lastSessionOptions = options;
  await persistSavedSession(createSavedSessionSnapshot());
  paused = false;
  renderStudyScreen();
  await requestWakeLock();
}

async function resumeSavedSession(deck: DeckRecord, saved: SavedSessionRecord, subdeck?: SubdeckSummary): Promise<void> {
  undoableOperations = [];
  sessionSnapshotTimestamp = Math.max(sessionSnapshotTimestamp, saved.updatedAt);
  const savedSprintMinutes = normalizeSprintMinutes(saved.options.sprintMinutes ?? 0);
  const maximumSprintMs = savedSprintMinutes * 60_000;
  saved = {
    ...saved,
    options: { ...saved.options, sprintMinutes: savedSprintMinutes },
    sprintRemainingMs: maximumSprintMs > 0
      ? Math.min(maximumSprintMs, Math.max(0, saved.sprintRemainingMs ?? maximumSprintMs))
      : 0,
  };
  stopSprintTimer();
  sprintRemainingMs = Math.max(0, saved.sprintRemainingMs ?? (saved.options.sprintMinutes ?? 0) * 60_000);
  sprintExpired = false;
  showingTodayHiddenPrompt = false;
  await refreshTodayHiddenState(deck.id);
  const reviewTiming = reviewTimingForDeck(deck.id);
  const dayStartedAt = studyDayStartAt(Date.now(), reviewTiming.dayStartMinutes);
  const [allCards, progress, reviewFlags, dailyNewState, dailyReviewState] = await Promise.all([
    getCards(deck.id),
    getProgress(deck.id),
    getReviewFlags(deck.id),
    getDailyNewState(deck.id, dayStartedAt),
    getDailyReviewState(deck.id, dayStartedAt),
  ]);
  activeDailyNewCardIds = dailyNewCardIdsForDay(dailyNewState, progress, dayStartedAt);
  activeDailyNewDayStartedAt = dayStartedAt;
  activeDailyReviewCardIds = new Set(dailyReviewState.cardIds);
  activeDailyReviewDayStartedAt = dailyReviewState.dayStartedAt;
  const dailyConfiguration = dailyLimitSessionConfiguration(
    deck.id,
    subdeck,
    allCards,
    progress,
    activeDailyNewCardIds,
    activeDailyReviewCardIds,
    dayStartedAt,
  );
  const cards = subdeck ? allCards.filter((card) => card.sourceDeckId === subdeck.sourceDeckId) : allCards;
  activeSessionCards = cards;
  activeReviewFlags = new Set(reviewFlags.map((item) => item.cardId));
  const resumed = new StudySession(
    cards,
    progress,
    saved.options,
    saved,
    activeReviewFlags,
    reviewTiming,
    dailyConfiguration.policy,
    dailyConfiguration.introducedCardIds,
    dailyConfiguration.sourceDeckNewLimits,
    dailyConfiguration.reviewCardIds,
    dailyConfiguration.reviewedCardIds,
    dailyConfiguration.dailyReviewLimit,
    dailyConfiguration.sourceDeckReviewLimits,
  );
  resumed.excludeCardIds(new Set([...activeTodayHidden, ...activeSiblingBuried]));
  activeDeck = deck;
  activeSubdeck = subdeck;
  session = resumed;
  lastSessionOptions = saved.options;
  paused = false;
  renderStudyScreen();
  await requestWakeLock();
}

