import type { DailyLimits, DeckTodayCounts, StudyScopeTodayCounts } from "./types";

export interface TodayQuotaView {
  newCards: number;
  reviewCards: number;
  dailyNewLimit: number;
  dailyReviewLimit: number;
  newLimitReached: boolean;
  reviewLimitReached: boolean;
}

function freshUnseen(scope: StudyScopeTodayCounts): number {
  return Math.max(0, scope.unseenCount - scope.introducedUnreviewedCount);
}

function remainingSlots(limit: number, introducedCount: number): number {
  return limit > 0 ? Math.max(0, limit - introducedCount) : Number.POSITIVE_INFINITY;
}

export function subdeckTodayQuota(
  scope: StudyScopeTodayCounts,
  limits: DailyLimits,
  introducedCountForLimit = scope.introducedCount,
  reviewedCountForLimit = scope.reviewedCount,
): TodayQuotaView {
  const newSlots = remainingSlots(limits.newCards, introducedCountForLimit);
  const reviewSlots = remainingSlots(limits.reviews, reviewedCountForLimit);
  const fresh = Math.min(freshUnseen(scope), newSlots);
  const freshReviews = Math.max(0, scope.dueReviewCount - scope.reviewedDueCount);
  return {
    newCards: scope.introducedUnreviewedCount + fresh,
    reviewCards: scope.reviewedDueCount + Math.min(freshReviews, reviewSlots),
    dailyNewLimit: limits.newCards,
    dailyReviewLimit: limits.reviews,
    newLimitReached: limits.newCards > 0 && newSlots <= 0 && freshUnseen(scope) > 0,
    reviewLimitReached: limits.reviews > 0 && reviewSlots <= 0 && freshReviews > 0,
  };
}

export function deckTodayQuota(
  counts: DeckTodayCounts,
  limits: DailyLimits,
  subdeckLimits: ReadonlyMap<string, DailyLimits>,
): TodayQuotaView {
  let freshAllowedBySubdecks = 0;
  let freshReviewsAllowedBySubdecks = 0;
  for (const [sourceDeckId, scope] of Object.entries(counts.subdecks)) {
    const subdeckLimit = subdeckLimits.get(sourceDeckId) ?? { newCards: 0, reviews: 0 };
    freshAllowedBySubdecks += Math.min(
      freshUnseen(scope),
      remainingSlots(subdeckLimit.newCards, scope.introducedCount),
    );
    freshReviewsAllowedBySubdecks += Math.min(
      Math.max(0, scope.dueReviewCount - scope.reviewedDueCount),
      remainingSlots(subdeckLimit.reviews, scope.reviewedCount),
    );
  }
  const newSlots = remainingSlots(limits.newCards, counts.parent.introducedCount);
  const reviewSlots = remainingSlots(limits.reviews, counts.parent.reviewedCount);
  const fresh = Math.min(
    freshAllowedBySubdecks,
    newSlots,
  );
  const freshReviews = Math.min(freshReviewsAllowedBySubdecks, reviewSlots);
  return {
    newCards: counts.parent.introducedUnreviewedCount + fresh,
    reviewCards: counts.parent.reviewedDueCount + freshReviews,
    dailyNewLimit: limits.newCards,
    dailyReviewLimit: limits.reviews,
    newLimitReached: limits.newCards > 0 && newSlots <= 0 && freshAllowedBySubdecks > 0,
    reviewLimitReached: limits.reviews > 0 && reviewSlots <= 0 && freshReviewsAllowedBySubdecks > 0,
  };
}
